pub fn dispatch_bump(
    repo: &mut impl crate::kernel::Repository<Tally>,
    id: &str,
    args: BumpArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Tally> {
    args.by.check_invariants()?;
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, TALLY_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Bump",
        "Tallying::Tally",
        "Tally",
        "tag.value",
        &with_references,
        &[crate::kernel::GivenSpec {
            description: "the sum stays positive",
            expr: Expr::Compare {
                op: crate::kernel::Comparison {
                    less_than: true,
                    equal: true,
                    negated: true,
                },
                left: Box::new(Expr::Add(
                    Box::new(Expr::Lookup("count.value")),
                    Box::new(Expr::Lookup("by.value")),
                )),
                right: Box::new(Expr::Int(0)),
            },
            corrects_event: None,
        }],
        None,
        |record| {
            {
                let current = record.count.clone().unwrap_or(Count { value: 0 });
                record.count = Some(Count {
                    value: {
                        let amount = args.by.value;
                        current.value.checked_add(amount).ok_or_else(|| {
                            crate::kernel::Refusal::Fault(format!(
                                "increment overflowed: {} + {} does not fit in a 64-bit integer",
                                current.value, amount
                            ))
                        })?
                    },
                    ..current
                });
            }
            Ok(())
        },
        &[],
        &tally_invariants(),
        &["CountBumped"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

